declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Fault : BOOL;
    Ack : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL := FALSE;
    Acknowledged : BOOL := FALSE;
    Horn : BOOL;
END_VAR
VAR
PreviousFault : BOOL := FALSE;
    Rising : BOOL;
END_VAR

implementation:
Rising := Fault AND NOT PreviousFault;
IF Reset AND NOT Fault THEN
    Alarm := FALSE; Acknowledged := FALSE;
ELSIF Fault THEN
    Alarm := TRUE;
    IF Rising THEN Acknowledged := FALSE; ELSIF Ack THEN Acknowledged := TRUE; END_IF;
ELSIF Alarm AND Ack THEN
    Acknowledged := TRUE;
END_IF;
Horn := Alarm AND NOT Acknowledged;
PreviousFault := Fault;
